                      filter: 'saturate(0.8) contrast(0.95) sepia(0.1)',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontFamily: 'var(--font-serif)',
                      fontStyle: 'italic',
                      color: 'rgba(43, 43, 43, 0.4)',
                      fontSize: '1.25rem',
