      <section className="section" style={{ paddingTop: 'var(--space-24)', paddingBottom: 'var(--space-24)' }}>
        <div className="container" style={{ textAlign: 'center' }}>
          <div className={`reveal ${revealed.includes(10) ? 'active' : ''}`}>
            <p className="section-label">Let's Collaborate</p>
            <h2 className="section-title" style={{ marginBottom: 'var(--space-8)' }}>
              Ready to elevate<br />your brand?
